def get_radius_and_diam(n, adj):
    ecc = []
    for i in range(n):
        d = [-1]*n
        d[i] = 0
        q = [i]
        for u in q:
            for v in adj[u]:
                if d[v] == -1:
                    d[v] = d[u] + 1
                    q.append(v)
        if any(x == -1 for x in d): return None, None
        ecc.append(max(d))
    return min(ecc), max(ecc)

# Let us test various graph families:
# 1. Cycles C_n
# 2. Paths P_n
# 3. Grids P_a x P_b
# 4. Prisms C_a x K_2
# 5. Mobius ladders
# 6. Generalized Petersen P(n, k)
